import { useMemo } from 'react';

import { getAggregatedCluster } from '../functions/get-aggregated-cluster.js';
import { InternalTreeMapRootNode } from '../types/internal.js';

/**
 * Calculates the aggregated data for a treemap based on the provided data and treemap area.
 * @param data - TreeMap data
 * @param treemapArea - available area for the TreeMap
 * @returns - TreeMap data with aggregated nodes for each cluster
 */

export const useAggregatedData = (
  data: InternalTreeMapRootNode,
  treemapArea: number,
  minNodeSize: number,
): InternalTreeMapRootNode => {
  const areaPerValue = treemapArea / data.value;
  const aggregatedClusters = useMemo(
    () =>
      data.children?.map((node) =>
        getAggregatedCluster(node, areaPerValue, minNodeSize),
      ),
    [areaPerValue, data.children, minNodeSize],
  );

  return { ...data, children: aggregatedClusters };
};
